INSERT INTO venue (venue_name, road_address, detail_address, notice, created_at, modified_at) VALUES
('서울 아트센터','서울특별시 강남구 테헤란로 101','지하 2층 주차장 이용 가능','공연 시작 30분 전까지 입장해 주세요.','2026-07-21 15:00:00','2026-07-21 15:00:00'),
('한강 문화회관','서울특별시 영등포구 여의대로 45','3층 안내데스크에서 티켓 수령','공연 시작 10분 전까지 입장해 주세요.','2026-07-21 15:00:00','2026-07-21 15:00:00'),
('인천 공연예술관','인천광역시 남동구 예술로 172','공연장 전용 주차장 이용 가능','공연 중 사진 및 영상 촬영은 제한됩니다.','2026-07-21 15:00:00','2026-07-21 15:00:00'),
('수원 시민극장','경기도 수원시 팔달구 효원로 241','수원시청역 5번 출구 도보 8분','공연장 내에서는 정숙해 주세요.','2026-07-21 15:00:00','2026-07-21 15:00:00'),
('부산 오션아트홀','부산광역시 해운대구 센텀중앙로 55','센텀시티역 6번 출구 연결','공연장 내 음식물 반입이 제한됩니다.','2026-07-21 15:00:00','2026-07-21 15:00:00'),
('대전 컨벤션아트센터','대전광역시 유성구 엑스포로 107','컨벤션센터 동관 2층','공연 티켓을 미리 준비해 주세요.','2026-07-21 15:00:00','2026-07-21 15:00:00'),
('대구 뮤직아레나','대구광역시 북구 엑스코로 10','서관 입구를 이용해 주세요','공연 종료 후 순차 퇴장해 주세요.','2026-07-21 15:00:00','2026-07-21 15:00:00'),
('광주 빛고을극장','광주광역시 서구 상무중앙로 61','지하철 상무역 도보 5분','객석 내 휴대전화는 무음으로 설정해 주세요.','2026-07-21 15:00:00','2026-07-21 15:00:00'),
('울산 문화예술센터','울산광역시 남구 번영로 200','문화예술회관 제2주차장 이용','휠체어석은 사전 문의가 필요합니다.','2026-07-21 15:00:00','2026-07-21 15:00:00'),
